          ..write('targetHourlyMinor: $targetHourlyMinor, ')
          ..write('currency: $currency, ')
          ..write('status: $status, ')
          ..write('closedAt: $closedAt, ')
          ..write('rowid: $rowid')
          ..write(')'))
        .toString();
  }
}

